"""Complete 28 original Sjogren/IgG4-related disease questions."""
from create_rheum_sjogren import rows,q,C,B,ref
from qbank_authoring import finalize
IC=ref('ACR/EULAR 2019 IgG4-related disease classification criteria','https://ard.bmj.com/content/79/1/77')
IP=ref('International consensus on IgG4-related disease pathology','https://pubmed.ncbi.nlm.nih.gov/22596100/')
IT=ref('International IgG4-related disease management consensus','https://doi.org/10.1002/art.39132')
IN=ref('MITIGATE original inebilizumab randomized trial','https://www.nejm.org/doi/10.1056/NEJMoa2409712')
UL=ref('DailyMed Uplizna prescribing information: updated 2026','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=834db232-afb0-4dcf-93e0-009ce8245c20')

q('An older man has painless bilateral submandibular enlargement, lacrimal swelling and autoimmune pancreatitis. Biopsy shows a compatible fibroinflammatory pattern. Which diagnosis best unifies the findings?', 'IgG4-related disease',[
 ('Primary Sjogren disease','Sicca and lymphocytic gland disease can overlap clinically, but the male tumefactive multiorgan fibroinflammatory pattern and pancreatitis favor IgG4-RD.'),('Sarcoidosis','Noncaseating granulomas and a compatible systemic pattern would support sarcoid rather than the stated fibroinflammatory disease.'),('Multicentric Castleman disease','This usually has a different inflammatory/lymphoid pattern and must be distinguished by pathology and the systemic presentation.')],
 'Recognize a multiorgan tumefactive phenotype','**IgG4-RD can involve salivary/lacrimal glands, pancreas, bile ducts, kidneys and retroperitoneum.**',['The diagnosis requires integrated clinical, imaging and pathological assessment.','Lymphoma, infection and other inflammatory disorders are important mimics.'], '**Map the organ involvement and choose informative tissue.**',['Do not diagnose solely from an elevated serum subclass.','Assess whether any lesion is threatening organ function.'],[['Gland enlargement','Can be tumefactive'],['Pancreatitis/other organs','Suggests systemic process'],['Tissue','Needed in many uncertain cases']],[IC,IP],style='clinical_scenario')

q('Which histological combination most strongly supports IgG4-related disease in the appropriate organ and clinical context?', 'Dense lymphoplasmacytic inflammation, storiform fibrosis and obliterative phlebitis',[
 ('Caseating granulomas and acid-fast organisms','This supports mycobacterial infection.'),('Necrotizing granulomatous vasculitis with pauci-immune glomerulonephritis','This supports an ANCA-associated process.'),('Monomorphic clonal lymphoid infiltration','This raises concern for lymphoma rather than a benign polyclonal fibroinflammatory lesion.')],
 'Architecture matters as well as immunostaining','**The characteristic pathological triad supports IgG4-RD, though its prominence varies by organ.**',['IgG4-positive plasma-cell counts and ratios are interpreted using organ-specific standards.','IgG4-rich infiltrates can occur in mimics and are not sufficient in isolation.'], '**Ask for integrated expert pathology review.**',['Preserve the possibility of infection and malignancy in the differential.','A small inadequate sample may not reveal the full architecture.'],[['Storiform fibrosis','Characteristic architecture'],['Obliterative phlebitis','Important supporting feature'],['IgG4 cells alone','Insufficient for every case']],[IP])

q('Which statement about serum IgG4 is correct?', 'It can be normal in genuine IgG4-RD and elevated in several mimics',[
 ('A normal value excludes IgG4-RD','Serum sensitivity is incomplete.'),('Any elevation proves IgG4-RD regardless of pathology','Allergic, infectious, malignant and other inflammatory states can raise IgG4.'),('Its concentration alone measures irreversible fibrosis accurately','A serum subclass does not directly quantify fixed tissue damage.')],
 'Use a serum subclass as supporting evidence','**Serum IgG4 is neither a universally sensitive nor uniquely specific diagnostic test.**',['The magnitude of elevation and organ pattern affect interpretation.','Biopsy and imaging may carry more diagnostic value in a particular case.'], '**Avoid treating a laboratory result instead of a defined disease.**',['Establish the clinically active lesions and exclude mimics.','Response monitoring should include organ function and imaging when relevant.'],[['Normal IgG4','Does not exclude'],['Raised IgG4','Not diagnostic alone'],['Follow-up','Organ-specific evidence remains important']],[IC,IP])

q('A pancreatic biopsy shows lymphoplasmacytic sclerosing pancreatitis with storiform fibrosis and abundant IgG4-positive plasma cells. Which subtype is most likely?', 'Type 1 autoimmune pancreatitis',[
 ('Type 2 autoimmune pancreatitis','This is IgG4-unrelated and classically emphasizes granulocytic epithelial lesions.'),('Alcohol-related chronic pancreatitis','This has a different exposure and pathological pattern.'),('Pancreatic ductal adenocarcinoma','Cancer must be excluded in a mass presentation but does not explain this characteristic inflammatory architecture.')],
 'Type 1 AIP is a pancreatic IgG4-RD manifestation','**The described lymphoplasmacytic sclerosing pattern supports type 1 autoimmune pancreatitis.**',['Associated bile duct, gland, retroperitoneal or renal disease can support the systemic diagnosis.','Type 2 AIP has a different pathological and clinical association profile.'], '**Investigate a pancreatic mass carefully before using treatment response as a diagnostic shortcut.**',['A mild serum IgG4 elevation does not exclude cancer.','Use the full imaging, tissue and clinical assessment.'],[['Type 1','IgG4-related'],['Type 2','Granulocytic epithelial lesion phenotype'],['Mass lesion','Exclude malignancy']],[ref('Autoimmune pancreatitis biopsy interpretation','https://pubmed.ncbi.nlm.nih.gov/38184420/')],style='clinical_scenario')

q('Which finding more strongly supports type 2 autoimmune pancreatitis than type 1?', 'Granulocytic epithelial lesions with an associated inflammatory bowel disease context',[
 ('IgG4-related retroperitoneal fibrosis','This supports a systemic type 1 IgG4-related phenotype.'),('Marked IgG4-rich storiform sialadenitis','This supports IgG4-RD and thus type 1 AIP.'),('IgG4-related tubulointerstitial nephritis','This is another systemic IgG4 manifestation.')],
 'Do not place every autoimmune pancreatitis case in IgG4-RD','**Type 2 AIP is generally IgG4-unrelated and has a duct-centric neutrophilic pathological pattern.**',['IBD is an important association.','The pathological finding must still be interpreted in an appropriate background and with drug-related pancreatitis considered.'], '**Use subtype-specific evidence.**',['Serum IgG4 may not provide a useful diagnostic marker in type 2 disease.','Both subtypes require careful exclusion of cancer and other causes.'],[['Type 2','Duct-centric/GEL pattern'],['IBD','Important association'],['Type 1','Systemic IgG4 phenotype']],[ref('Type 2 AIP consensus and controversies','https://pmc.ncbi.nlm.nih.gov/articles/PMC9099380/')])

q('An older patient has obstructive jaundice, a focal pancreatic head mass and mildly raised IgG4. What is the most appropriate principle?', 'Exclude pancreatic malignancy through an appropriate diagnostic pathway before attributing the mass to IgG4-RD',[
 ('Use mild IgG4 elevation as definitive proof of autoimmune pancreatitis','The marker is not uniquely specific.'),('Start glucocorticoids as the only diagnostic test without cancer evaluation','This can delay or obscure diagnosis of a malignancy or other lesion.'),('Exclude cancer because autoimmune pancreatitis can respond to steroids','Potential responsiveness does not establish the diagnosis before evaluation.')],
 'A mass requires more than a serum subclass result','**Pancreatic cancer is a major mimic of focal autoimmune pancreatitis.**',['Use detailed imaging, endoscopic assessment and tissue when indicated.','Other organ findings and characteristic histology can increase confidence in IgG4-RD.'], '**Avoid an unsupervised diagnostic steroid trial.**',['Treatment response is interpreted only within an appropriate specialist workup.','Manage biliary obstruction and infection according to clinical urgency.'],[['Mild IgG4 elevation','Insufficient alone'],['Focal mass','Cancer workup needed'],['Steroid trial','Only within a justified diagnostic plan']],[IC,ref('Autoimmune pancreatitis biopsy interpretation','https://pubmed.ncbi.nlm.nih.gov/38184420/')],style='clinical_scenario')

q('A man with IgG4-RD develops bilateral hydronephrosis and a periaortic soft-tissue rind encasing the ureters. Which manifestation is most likely?', 'IgG4-related retroperitoneal fibrosis',[
 ('Bilateral intraluminal ureteric calculi','Stones do not best explain a circumferential periaortic fibroinflammatory rind.'),('Isolated proliferative glomerulonephritis','This does not account for ureteric encasement and obstructive dilation.'),('Uncomplicated bladder overactivity','This does not produce the stated retroperitoneal lesion.')],
 'Fibroinflammation can obstruct an organ indirectly','**Retroperitoneal fibrosis can encase the ureters and cause obstructive kidney injury.**',['Lymphoma, malignancy and non-IgG4 fibrosis are important alternative causes.','Renal function can deteriorate despite limited urinary symptoms.'], '**Relieve clinically important obstruction and treat the underlying process.**',['Urological drainage may be necessary before medical treatment has time to work.','Use imaging and tissue assessment to establish the cause and follow response.'],[['Periaortic rind','Fibrosing retroperitoneal process'],['Hydronephrosis','Ureteric obstruction'],['Management','Drainage when needed plus disease treatment']],[IC,IT],style='clinical_scenario')

q('An IgG4-RD patient has rising creatinine, hypocomplementemia and multiple cortical renal lesions. Which pathology is particularly characteristic?', 'IgG4-related tubulointerstitial nephritis',[
 ('Minimal change disease as the defining renal lesion','This is not the characteristic parenchymal lesion in the stated systemic context.'),('Anti-GBM crescentic nephritis','This requires a different serological and pathological mechanism.'),('Diabetic nodular sclerosis as proven by low complement','Low complement and systemic IgG4 features do not establish diabetic nephropathy.')],
 'IgG4 can affect renal parenchyma as well as cause obstruction','**Tubulointerstitial nephritis is a major IgG4-related kidney pattern.**',['Hypocomplementemia and characteristic imaging findings can be clues.','Membranous nephropathy and other lesions can also occur.'], '**Consider biopsy when it will define the mechanism and guide treatment.**',['Distinguish active inflammation from chronic fibrosis.','Assess obstruction, medications and other renal diseases concurrently.'],[['Tubulointerstitial disease','Characteristic IgG4 renal pattern'],['Complement','May be low'],['Obstruction','A separate renal injury mechanism']],[ref('IgG4-related kidney disease clinicopathological cohort','https://pubmed.ncbi.nlm.nih.gov/39156178/')],style='clinical_scenario')

q('A patient has lymphadenopathy with many IgG4-positive plasma cells but no other characteristic organ lesions. What is the most appropriate interpretation?', 'The finding alone is insufficient; evaluate reactive, infectious, malignant and other inflammatory causes',[
 ('It establishes IgG4-RD regardless of architecture','IgG4-rich lymphadenopathy is not uniquely specific.'),('It excludes lymphoma in all cases','Appropriate morphology and clonality assessment may still be needed.'),('It proves a pancreatic IgG4 manifestation even with normal pancreatic assessment','An organ manifestation cannot be inferred solely from a lymph-node stain.')],
 'Choose tissue for architecture and differential diagnosis','**Lymph-node IgG4 staining alone can be misleading.**',['Characteristic storiform fibrosis and phlebitis may be less evident in nodes.','Some mimics have substantial IgG4-positive plasma-cell populations.'], '**Integrate pathology with imaging and the systemic phenotype.**',['A different affected organ may provide more specific tissue when safe to sample.','Do not let a positive stain terminate the lymphoma evaluation prematurely.'],[['IgG4-rich node','Not specific alone'],['Architecture/clonality','Important for mimics'],['Other organ tissue','May improve diagnostic specificity']],[IP,IC])

q('Which endocrine manifestation can occur in IgG4-RD?', 'Hypophysitis with pituitary hormone deficiency and/or diabetes insipidus',[
 ('A toxic thyroid adenoma as the characteristic IgG4 lesion','This is not the defining IgG4 endocrine phenotype.'),('Insulinoma as the expected consequence of autoimmune pancreatitis','These are distinct disease processes.'),('Pheochromocytoma as the usual IgG4 cause of hypertension','This is not the characteristic mechanism.')],
 'The fibroinflammatory process can involve the pituitary','**IgG4-related hypophysitis can affect anterior or posterior pituitary function.**',['Mass effect and infiltrative changes require a careful differential.','Malignancy, infection, sarcoid and other hypophysitis forms can mimic it.'], '**Assess adrenal and thyroid axes and water balance promptly.**',['Hormone replacement may be urgent regardless of the eventual immune diagnosis.','A systemic organ pattern and tissue evidence can support attribution.'],[['Anterior pituitary','Hormonal deficiencies'],['Posterior pituitary/stalk','Diabetes insipidus possible'],['Urgency','Identify adrenal insufficiency']],[IC,IT])

q('A patient has active symptomatic IgG4-RD threatening renal function after infection and malignancy have been appropriately assessed. Which initial treatment principle is reasonable?', 'Prompt disease-directed therapy, often glucocorticoid induction with a plan for relapse prevention or steroid sparing',[
 ('Observe indefinitely until irreversible renal failure establishes disease severity','Organ threat favors treatment before fixed damage accumulates.'),('Treat only the serum IgG4 concentration without organ assessment','The target is active disease and organ preservation, not a number alone.'),('Use antibiotics alone for a sterile confirmed fibroinflammatory process','Antibiotics do not substitute for immune treatment when infection has been excluded.')],
 'Treat active organ-threatening inflammation before it becomes fixed fibrosis','**Glucocorticoids can induce remission in many active IgG4-RD manifestations.**',['Relapse is common and prolonged steroid toxicity is important.','B-cell-directed and other steroid-sparing strategies are chosen according to current evidence, approvals and patient risk.'], '**Plan induction, taper and response monitoring together.**',['Relieve obstructive complications when necessary.','Track organ function and imaging rather than serum IgG4 alone.'],[['Active inflammation','Often treatment-responsive'],['Fixed fibrosis','May be less reversible'],['Long-term plan','Relapse and toxicity prevention']],[IT,IN],style='clinical_scenario')

q('Which target is bound by inebilizumab, now approved in the US for adults with IgG4-related disease?', 'CD19',[
 ('CD20','This is the target of rituximab and obinutuzumab.'),('BAFF','This is targeted by belimumab.'),('IL-6 receptor','This is targeted by tocilizumab and sarilumab.')],
 'Recognize the new B-cell-directed IgG4-RD treatment','**Inebilizumab is a CD19-directed cytolytic antibody.**',['The MITIGATE trial showed reduced flare risk in active IgG4-RD.','US approval for adult IgG4-RD occurred in 2025; local availability and licensing can differ.'], '**Use current prescribing information rather than older statements that no treatment is approved.**',['Review infection risks, immunoglobulins and vaccination timing.','The indication does not eliminate the need to establish the diagnosis carefully.'],[['Inebilizumab','CD19'],['Rituximab','CD20'],['Belimumab','BAFF']],[IN,UL,ref('FDA adult IgG4-RD approval record','https://www.accessdata.fda.gov/scripts/opdlisting/oopd/detailedIndex.cfm?cfgridkey=1026624')])

q('Which pre-treatment checks are specifically relevant before inebilizumab?', 'HBV and TB screening, quantitative immunoglobulins and review of vaccination/infection status',[
 ('Only serum IgG4, because total immunoglobulins and infection history do not matter','B-cell depletion can cause hypogammaglobulinemia and infection complications.'),('Only HLA-B*58:01 testing','This is an allopurinol safety association, not the defining inebilizumab screen.'),('Only retinal OCT','Retinal screening is important for hydroxychloroquine, not the principal inebilizumab preparation.')],
 'Prepare for broad B-cell-directed treatment','**The label requires attention to HBV, TB and quantitative immunoglobulin status.**',['Avoid treatment during important active infection and follow contraindications.','Plan vaccines before immune depletion when feasible.'], '**Monitor infection and immunoglobulins during treatment.**',['Discuss infusion reactions and follow the required administration precautions.','A fall in IgG4 should not distract from harmful broader immunoglobulin suppression.'],[['HBV/TB','Relevant infection screening'],['Immunoglobulins','Baseline and follow-up'],['Vaccination','Plan timing']],[UL])

q('A treated IgG4-RD patient has improved inflammatory activity but persistent fibrotic ureteric obstruction. Which explanation is most appropriate?', 'Fixed structural damage can persist despite control of immune inflammation',[
 ('Any residual obstruction proves that every immune treatment has failed','Damage and activity can be discordant.'),('Normal serum IgG4 proves no residual organ problem is possible','A serum marker cannot certify structural recovery.'),('More glucocorticoid always reverses mature fibrosis completely','Established fibrosis can be poorly reversible and require mechanical management.')],
 'Separate activity from damage when judging response','**Immune control may prevent further injury without fully reversing established fibrosis.**',['Follow organ function and imaging in addition to symptoms and serology.','Persistent obstruction may need urological or procedural management.'], '**Avoid escalating immune therapy solely to chase irreversible anatomy.**',['Reassess whether there is active disease, fixed damage or an alternative cause.','Balance relapse prevention against cumulative treatment toxicity.'],[['Activity','Potentially immune-treatment responsive'],['Damage','May persist after inflammation settles'],['Obstruction','Can need procedural treatment']],[IT,IC],style='clinical_scenario')

if __name__=='__main__':finalize('Rheumatology',6,'Sjogren Syndrome and IgG4-related Disease','rheum-sjogren-igg4',rows,28)
